#pragma once
#include "snapshot_wire.hpp"
namespace ledger_format {
inline std::string real(double value){std::ostringstream out;out<<std::setprecision(17)<<value;return out.str();}
inline std::string initial(const device_retry::Command& c,unsigned n,const std::string& caseId,double T){return "initial\t"+std::to_string(n)+"\t"+caseId+"\t"+real(c.execGateAt)+"\t"+std::to_string(c.status)+"\t"+device_retry::hex(c.reason)+"\t"+device_retry::hex(c.output)+"\t"+device_retry::hex(c.error)+"\t"+real(c.pre)+"\t"+real(c.post)+"\t"+std::to_string(c.gatePassed)+"\t"+std::to_string(c.reaped)+"\tT_offset="+real(c.execGateAt-T);}
inline std::string snapshot(const device_retry::Command& call,unsigned n,std::uint64_t g,const std::string& attempt){return "snapshot\t"+std::to_string(n)+"\t"+std::to_string(g)+"\t"+attempt+"\t"+real(call.pre)+"\t"+real(call.post)+"\t"+std::to_string(call.status)+"\t"+std::to_string(call.gatePassed)+"\t"+std::to_string(call.reaped)+"\t"+device_retry::hex(call.reason)+"\t"+device_retry::hex(call.output)+"\t"+device_retry::hex(call.error);}
inline std::string retry(const device_retry::Command& c,const device_retry::Command& proof,const std::string& reason,unsigned slot,unsigned n,const std::string& attempt,bool submitted){return "retry\t"+std::to_string(slot)+"\t"+std::to_string(n)+"\t"+attempt+"\t"+std::to_string(submitted)+"\t"+real(c.execGateAt)+"\t"+std::to_string(c.status)+"\t"+device_retry::hex(reason)+"\t"+device_retry::hex(c.reason)+"\t"+device_retry::hex(c.output)+"\t"+device_retry::hex(c.error)+"\t"+real(c.pre)+"\t"+real(c.post)+"\t"+std::to_string(c.gatePassed)+"\t"+std::to_string(c.reaped)+"\t"+real(proof.pre)+"\t"+real(proof.post)+"\t"+std::to_string(proof.status)+"\t"+device_retry::hex(proof.output)+"\t"+device_retry::hex(proof.reason);}
}
